PRAGMA page_size=1024; CREATE TABLE t1(a INTEGER, b INTEGER, c TEXT); CREATE INDEX i1a ON t1(a); CREATE INDEX i1b ON t1(b); CREATE INDEX i1c ON t1(c); CREATE TABLE t2(a INTEGER, b INTEGER, c TEXT); CREATE INDEX i2a ON t2(a); CREATE INDEX i2b ON t2(b); WITH RECURSIVE seq(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM seq WHERE i<50000) INSERT INTO t2 SELECT i, (i*1664525+1013904223)%500000, printf('number %d',(i*1664525+1013904223)%500000) FROM seq; INSERT INTO t1 SELECT * FROM t2;